"""Publish only terminal, independently verified validation and authorized maintenance."""
import json,re
from pathlib import Path
B=Path(__file__).resolve().parent;R=B.parents[1]
v=json.loads((B/'free-erp-report-aggregate-oct10-full-independent.json').read_text());assert v['status']=='PASS'
log=(B/'free-erp-report-aggregate-oct10-full.log').read_text(encoding='utf-8-sig');m=re.search(r'test result: ok\. 625 passed; 0 failed; 0 ignored;.*?finished in ([\d.]+)s',log);assert m
unit=(B/'free-erp-report-aggregate-oct10-unit.log').read_text(encoding='utf-8-sig');assert '2 passed; 0 failed; 0 ignored' in unit
cleanup=json.loads((B/'free-erp-200g-oct10-authorized-cleanup.json').read_text());assert cleanup['status']=='PASS'
strict=[]
for line in (B/'free-erp-report-aggregate-oct10-repo-clippy.jsonl').read_text(encoding='utf-8-sig').splitlines():
 try:r=json.loads(line)
 except:continue
 if r.get('reason')=='compiler-message' and r['message']['level']=='error':strict.append(r['message'])
new=[r for r in strict if any('report_sources.rs' in s['file_name'] or 'operation_reports.rs' in s['file_name'] for s in r['spans'])]
report={'date':'2026-10-10','product_status':'PARTIAL','budget_gib':200,'automatic_cleanup':'Registered failed working sessions with compiler failure proof, boundary/reparse/exclusive occupancy checks, same build.lock; only approved paths removed','cleanup':cleanup,'validation':{'unit_passed':2,'source_focused_passed':6,'current_full_passed':625,'debug_seconds':float(m.group(1)),'independent':{k:v[k] for k in ['status','checks','protected_tenants','protected_tables','protected_rows','source_inputs']},'repo_strict':'FAIL' if strict else 'PASS','repo_error_instances':len(strict),'new_report_leaf_diagnostics':len(new)},'features':['Complete verified rows aggregated once with wide intermediate values; context, selected totals and new admission share the actual snapshot','Large valid report/reversal net independent of UUID order; invalid final totals never zero-clamped','Fixed G target/home/tmp reused; 200GiB budget retains volume minimum20GiB and serial guard'], 'limits':['Reporting page, business employee/crew/unit refs, client pending/rejection handling and GUI still incomplete','Strict backend and Release scale, Worker, 323 installation/restore and official hosting remain incomplete','Current cleanup approval resolves the storage barrier; whole free ERP is not complete']}
p=B/'free-erp-200g-report-aggregate-oct10-delivery.json';assert not p.exists();p.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
text=f'''\n\n## 五十五 200GiB授权维护与单次报工汇总验证\n\n2026-10-10用户明确批准200G构建及自动清理，统一入口固定G盘缓存预算改为200GiB；原target/cargo-home/tmp、build.lock、至少20GiB空闲及固定工具链继续保持。ErpCacheMaintenance仅处理登记清单内编译失败证据明确的增量working目录，绝对边界/目录形状/重解析点/当前Rust工具/逐文件独占打开检查后才清理；预算超限时可自动登记同类编译失败目录。不能恢复准入仍拒绝，未授权其他缓存类别和进程终止。实际删除已批准两目录747293780字节，约0.696GiB，完整路径与UTC时间留证，旧待批准记录保留为历史。边界、增量根/完成目录拒绝探针与脚本语法检查通过。\n\n报工真实验证行一次按工序汇总，i128中间值后转换最终非负i64，避免报告/冲正UUID顺序造成中途溢出误拒；上下文/累计与新报工的本序/前序/后序保护复用同一验证结果，去掉循环SUM往返。两库边界测试、6真实API/PG源专项通过；当前完整625/0/0/0实际通过，{float(m.group(1))}秒为debug功能时长。[{v['checks']}独立核对](../qa/acceptance/free-erp-report-aggregate-oct10-full-independent.json)PASS，{v['protected_tenants']}旧企业{v['protected_tables']}表{v['protected_rows']}行和{v['source_inputs']}输入一致。仓储严格仍FAIL、{len(strict)}诊断实例，本两报工叶{len(new)}新增；不称API/发布严格通过。\n\n见[维护及汇总交付](../qa/acceptance/free-erp-200g-report-aggregate-oct10-delivery.json)与[实际清理](../qa/acceptance/free-erp-200g-oct10-authorized-cleanup.json)。80GiB阻塞与先前NOT_RUN是历史，当前授权与验证已解除该存储条件。正式报工页、员工/班组/单位业务引用、持久未决/确定拒绝绑定、GUI、严格后端、Worker、323安装恢复、Release规模及免费公网仍未完成，整体PARTIAL。\n'''
p=R/'docs/FREE_ERP_DEVELOPMENT_SPEC.md';s=p.read_bytes();assert '## 五十五'.encode() not in s;p.write_bytes(s+text.replace('\n','\r\n').encode())
road=f'''\n\n### 2026-10-10 用户授权200GiB与自动失效缓存维护\n\n明确批准预算200G与自动清理后，统一入口保留原G盘三存储及build.lock，预算200GiB、卷空闲至少20GiB。自动范围仅登记且有编译失败证据/无占用/无重解析点的增量working目录，预算超限可登记同类路径；完整增量/deps/执行文件/依赖下载/源码/Git/数据库/发布/备份/QA证据不清。两已批准路径实际移除0.696GiB，日志/清单保存，未终止其他进程。\n\n单次完整来源汇总、i128中间值与同快照消费的两库边界/6源专项通过；当前完整625/0/0/0，{float(m.group(1))}秒为debug功能时长。[{v['checks']}独立核对](../qa/acceptance/free-erp-report-aggregate-oct10-full-independent.json)保持{v['protected_tenants']}旧企业{v['protected_tables']}表{v['protected_rows']}行及{v['source_inputs']}输入。严格仓储仍FAIL，本两叶{len(new)}新诊断，不扩称发布门禁通过。先前80GiB/待清理/NOT_RUN为历史，当前批准已解决该资源阻塞。见[交付](../qa/acceptance/free-erp-200g-report-aggregate-oct10-delivery.json)。继续正式报工页/业务档案/未决恢复及双端，Worker/323安装恢复/Release/官方免费公网未完成，整体PARTIAL。\n'''
p=R/'docs/ROADMAP.md';s=p.read_bytes();assert '### 2026-10-10 用户授权200GiB'.encode() not in s;p.write_bytes(s+road.replace('\n','\r\n').encode());print('verified delivery and current policy recorded')
